sp_widget.client_script:
api.controller=function(spUtil,$rootScope,$scope) {
	/* widget controller */
	var c = this;

	$rootScope.$on('CaseId', function(event, sysId) {
		c.widgetinstance = false;
	})



	$rootScope.$on('AuditSysId', function(event, sysId) {
		//	console.log("recieved "+ sysId)
		if(sysId){
			$scope.receivedSysId = sysId;

			spUtil.get('kotak_form', {
				table: 'x_rptp_kotak_uw_case',
				view: 'coverage_details',
				sys_id: $scope.receivedSysId 
			}).then(response => {
				c.widgetinstance = response;
			});
		}
		else{

			c.widgetinstance = false;
		}
	});






};

sp_widget.css:
.widget-title {
  font-family: 'Arial', sans-serif;
  font-size: 24px;
  font-weight: bold;
  color: #03428E;
  background-color: #f9f9f9;
  padding: 20px;
  border-radius: 10px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  display: flex;
  align-items: center;
  justify-content: space-between;
  transition: background-color 0.3s ease;
  margin-bottom : 2rem;
}

.widget-title:hover {
  background-color: #e9e9e9;
}

.widget-title i {
  font-size: 24px;
  cursor: pointer;
}

.widget-title .exit-icon {
  margin-right: 10px;
}

.widget-title .content {
  flex-grow: 1; /* This ensures the content takes up available space */
  display: flex;
  justify-content: left; /* Centers the heading */
}

.widget-title .chart-icon {
  margin-left: 10px;
}
